import XCTest

final class RepostUITests: XCTestCase {
    func testOpenFirstPostRepostMenu() {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()
        sleep(2)
        app.coordinate(withNormalizedOffset: CGVector(dx: 0.376, dy: 0.701)).tap()
        sleep(1)
        XCTContext.runActivity(named: "Repost menu hierarchy") { activity in
            let attachment = XCTAttachment(string: app.debugDescription)
            attachment.name = "Repost menu hierarchy"
            activity.add(attachment)
        }
    }
}
EOF
